,"12","49","25"],"ans":0},{"id":"ALG-08-018","ch":8,"fmt":"Y1","lv":3,"stem":"Masalada n=100 va A(n)=n+10, B(n)=2n. Qaysi algoritm kam amal bajaradi?","exp":"A=110, B=200: A kam.","source":"2026 spetsifikatsiya, PDF 4 (maqbul algoritm tanlash)","diagram":null,"status":"review","construct":"S3.ALGO.04","opts":["A: 200 amal","B: 100 amal","A: 110 amal","B: 110 amal"],"ans":2},{"id":"ALG-08-019","ch":8,"fmt":"Y1","lv":4,"stem":"16 ta elementli saralangan massivni taxminan necha marta yarmiga bo‘lsak, interval hajmi 1 ga tushadi?","exp":"16=2^4, shuning uchun 4 ta yarmiga bo‘lish yetadi. Bu qidiruv taqqoslashlari soni bilan aynan teng bo‘lishi shart emas.","source":"2026 spetsifikatsiya, PDF 4 (maqbul algoritm tanlash)","diagram":null,"status":"review","construct":"S3.ALGO.04","opts":["5","4","3","6"],"ans":1},{"id":"ALG-08-020","ch":8,"fmt":"Y1","lv":4,"stem":"64 ta elementli intervalni 2 ga necha marta bo‘lsak 4 element qoladi?","exp":"64→32→16→8→4: to‘rtta bo‘lish.","source":"2026 spetsifikatsiya, PDF 4 (maqbul algoritm tanlash)","diagram":null,"status":"review","construct":"S3.ALGO.04","opts":["6","4","5","3"],"ans":1},{"id":"ALG-08-021","ch":8,"fmt":"Y1","lv":4,"stem":"128 ta interval 4 martalik yarmiga bo‘linganda hajmi nechaga teng?","exp":"128/2⁴=8.","source":"2026 spetsifikatsiya, PDF 4 (maqbul algoritm tanlash)","diagram":null,"status":"review","construct":"S3.ALGO.04","opts":["32","16","4","8"],"ans":3},{"id":"ALG-08-022","ch":8,"fmt":"Y1","lv":4,"stem":"A usulni tayyorlash 20 amal, so‘ng har so‘rov 2 amal; B usul har so‘rov 7 amal talab etadi. 5 ta so‘rov uchun qaysi biri tejamli?","exp":"A=20+5·2=30, B=5·7=35. Boshlang‘ich xarajatni ham hisoblash kerak.","source":"2026 spetsifikatsiya, PDF 4 (maqbul algoritm tanlash)","diagram":null,"status":"review","construct":"S3.ALGO.04","opts":["A: 30 amal; B: 35 amal; A tejamli","B, chunki 7 doim 2 dan katta","Ikkalasi ham 35 amal","A 40 amal, B 25 amal"],"ans":0},{"id":"ALG-08-023","ch":8,"fmt":"Y1","lv":4,"stem":"O(