turli usuldagi qadam soni n=3 bo‘lganda qaysi biri kam?\n\n**Chizma talab qilinadi:** algo_compare. Grafik qo‘shilmaguncha savol nashr qilinmasin.","exp":"A=3n=9, B=n²+3=12.","source":"2026 spetsifikatsiya, PDF 4: maqbul algoritm; qo‘shimcha mualliflik mazmuni","diagram":"algo_compare","status":"draft","construct":"S3.ALGO.04","opts":["A: 6, B: 12","A: 9, B: 12","B: 9, A: 12","Ikkalasi 12"],"ans":1},{"id":"ALG-08-029","ch":8,"fmt":"Y1","lv":5,"stem":"Ikki algoritm bir xil natija beradi: A faqat saralangan ro‘yxatda ishlaydi, B har qanday ro‘yxatda. Ro‘yxat saralanmagan va saralash mumkin bo‘lmasa, qaysi biri maqbul?","exp":"Tezlikdan oldin algoritmning kirish old sharti tekshiriladi.","source":"2026 spetsifikatsiya, PDF 4 (maqbul algoritm tanlash)","diagram":null,"status":"review","construct":"S3.ALGO.04","opts":["A, chunki nomi tezroq eshitiladi","A, chunki u yarmiga bo‘ladi","Ikkalasi, chunki har ikkalasi teng","B, chunki A ning zarur sharti bajarilmagan"],"ans":3},{"id":"ALG-08-030","ch":8,"fmt":"Y1","lv":5,"stem":"A algoritm 5n amal, B algoritm n² amal bajaradi. n=20 da qaysi nisbat B/A?","exp":"B/A=400/100=4.","source":"2026 spetsifikatsiya, PDF 4: maqbul algoritm; qo‘shimcha mualliflik mazmuni","diagram":null,"status":"review","construct":"S3.ALGO.04","opts":["4","5","8","2"],"ans":0}]'::jsonb)
 LOOP
  SELECT id INTO cid FROM public.constructs WHERE code=q->>'construct';
  lid:=md5('attestatsiya:algo-v2:lesson:'||(q->>'ch'))::uuid;
  IF cid IS NULL OR NOT EXISTS(SELECT 1 FROM public.lessons WHERE id=lid AND status='review') THEN
   RAISE EXCEPTION 'Missing review lesson/construct for %',q->>'id'; END IF;
  qid:=md5('attestatsiya:algo-v2:question:'||(q->>'id'))::uuid;
  IF EXISTS(SELECT 1 FROM public.questions WHERE id=qid) THEN CONTINUE; END IF;
  INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
  VALUES(qid,sid,cid,'S3.ALGO',(q->>'fmt')::question_format,
    (CASE WHEN (q->>'lv')::int<=2 THEN 'bilish' WHEN (q->>'lv')::int=3 THEN 'qollash' ELSE 'mulohaza' END)::cognitive_level,
    (q->>'lv')::int,q->>'stem','[]'::jsonb,true,(q->>'status')::content_status,
    'algoritmlash-v2:'||(q->>'id'),lid);
  IF q->>'fmt'='Y1' THEN
    FOR item,ord IN SELECT value,ordinality::int FROM jsonb_array_elements_text(q->'opts') WITH ORDINALITY
    LOOP
      idx:=ord-1;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(md5('attestatsiya:algo-v2:option:'||(q->>'id')||':a:'||idx)::uuid,qid,'a',idx,item);
    END LOOP;
    optid:=md5('attestatsiya:algo-v2:option:'||(q->>'id')||':a:'||(q->>'ans'))::uuid;
    payload:=jsonb_build_object('correct_option_id',optid::text);
  ELSIF q->>'fmt'='Y2' THEN
    FOR item,ord IN SELECT value,ordinality::int FROM jsonb_array_elements_text(q->'a') WITH ORDINALITY
    LOOP
      idx:=ord-1;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(md5('attestatsiya:algo-v2:option:'||(q->>'id')||':a:'||idx)::uuid,qid,'a',idx,item);
    END LOOP;
    FOR item,ord IN SELECT value,ordinality::int FROM jsonb_array_elements_text(q->'b') WITH ORDINALITY
    LOOP
      idx:=ord-1;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(md5('attestatsiya:algo-v2:option:'||(q->>'id')||':b:'||idx)::uuid,qid,'b',idx,item);
    END LOOP;
    payload:='{}'::jsonb;
    FOR p IN SELECT value FROM jsonb_array_elements(q->'pairs')
    LOOP
      lidx:=(p->>0)::int;ridx:=(p->>1)::int;
      payload:=payload||jsonb_build_object(
       md5('attestatsiya:algo-v2:option:'||(q->>'id')||':a:'||lidx)::uuid::text,
       md5('attestatsiya:algo-v2:option:'||(q->>'id')||':b:'||ridx)::uuid::text);
    END LOOP;
    payload:=jsonb_build_object('pairs',payload);
  ELSIF q->>'fmt'='Y3' THEN
    FOR item,ord IN SELECT value,ordinality::int FROM jsonb_array_elements_text(q->'a') WITH ORDINALITY
    LOOP
      idx:=ord-1;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(md5('attestatsiya:algo-v2:option:'||(q->>'id')||':a:'||idx)::uuid,qid,'a',idx,item);
    END LOOP;
    SELECT jsonb_build_object('order',jsonb_agg(md5('attestatsiya:algo-v2:option:'||(q->>'id')||':a:'||(value::int))::uuid::text ORDER BY ordinality))
     INTO payload FROM jsonb_array_elements_text(q->'seq') WITH ORDINALITY;
  ELSE RAISE EXCEPTION 'Unexpected format: %',q->>'fmt'; END IF;
  INSERT INTO public.question_keys(question_id,payload,explanation_md)
  VALUES(qid,payload,q->>'exp');
 END LOOP;
 IF (SELECT count(*) FROM public.questions WHERE source_reference LIKE 'algoritmlash-v2:ALG-%')<>240 THEN
  RAISE EXCEPTION 'Expected 240 Algoritmlash V2 questions'; END IF;
END $import$;
COMMIT;